  "lean_source": "import Std\n\nnamespace Contract\n\ninductive Edge where\n  | mk (u v : Nat)\n\ndef valid_input (n : Nat) (edges : List Edge) : Prop :=\n  n ≤ 10 ∧\n  (∀ e ∈ edges, e.1 < n ∧ e.2 < n)\n\ndef solve (n : Nat) (edges : List Edge) : List Nat × List Nat :=\n  if n = 0 then ([], [])\n  else\n    let adj : List (List Nat) := List.replicate n []\n    let indeg : List Nat := List.replicate n 0\n    let edges' := edges.filter (fun e => e.1 ≠ e.2)\n    let edges'' := edges'.dedup\n    let adj' : List (List Nat) :=\n      List.foldl (fun acc e =>\n        let i := e.1\n        let j := e.2\n        let rest := acc\n        let new_i := List.set! rest i (List.append (List.get! rest i) [j])\n        List.set! new_i j (List.get! new_i j)) adj edges''\n    let indeg' : List Nat :=\n      List.foldl (fun acc e =>\n        let j := e.2\n        let rest := acc\n        List.set! rest j (List.get! rest j + 1)) indeg edges''\n    let zero_indeg : List Nat :=\n      List.filter (fun i => List.get! indeg' i = 0) (List.range n)\n    let order : List Nat :=\n      List.foldl (fun acc _ =>\n        let min_v := List.get! zero_indeg 0\n        let rest := List.drop 1 zero_indeg\n        let new_indeg : List Nat :=\n          List.foldl (fun acc2 j =>\n            let rest2 := acc2\n            List.set! rest2 j (List.get! rest2 j - 1)) indeg' (List.get! adj' min_v)\n        let new_zero : List Nat :=\n          List.filter (fun i => List.get! new_indeg i = 0) (List.range n)\n        (acc, new_zero, new_indeg)) ([], zero_indeg, indeg') (List.range (n - 1))\n    let order_list : List Nat := List.cons (List.get! zero_indeg 0) (List.get! order 0)\n    let blocked : List Nat :=\n      List.filter (fun i => ¬ List.mem i order_list) (List.range n)\n    (order_list, blocked)\n\ndef valid (n : Nat) (edges : List Edge) : Prop :=\n  valid_input n edges\n\ntheorem thm_O1 (n : Nat) (edges : List Edge) (h : valid n edges) :\n  True := by sorry\n\ntheorem thm_O2 (n : Nat) (edges : List Edge) (h : valid n edges) :\n  True := by sorry\n\ntheorem thm_O3 (n : Nat) (edges : List Edge) (h : valid n edges) :\n  True := by sorry\n\ntheorem thm_O4 (n : Nat) (edges : List Edge) (h : valid n edges) :\n  True := by sorry\n\ntheorem thm_O5 (n : Nat) (edges : List Edge) (h : valid n edges) :\n  True := by sorry\n\ntheorem thm_O6 (n : Nat) (edges : List Edge) (h : valid n edges) :\n  n = 0 → solve n edges = ([], []) := by sorry\n\ntheorem non_vacuity :\n  ∃ (n : Nat) (edges : List Edge), valid n edges ∧ n = 0 ∧ solve n edges = ([], []) ∧\n  ∃ (n' : Nat) (edges' : List Edge), valid n' edges' ∧ n' = 2 ∧\n  solve n' edges' = ([0, 1], []) := by sorry\n\nend Contract",
